/** The first element that matches selector, or an error that names the selector. */
export function qs(selector, root = document) {
  const element = root.querySelector(selector);
  if (element === null) throw new Error(`Nothing matches ${selector}`);
  return element;
}

/** Every element that matches selector, as an array. */
export function qsa(selector, root = document) {
  return Array.from(root.querySelectorAll(selector));
}

function createRow(page) {
  const template = qs("#task-item", page);
  return template.content.firstElementChild.cloneNode(true);
}

function fillRow(row, task) {
  const titleId = `task-${task.id}-title`;
  row.dataset.id = task.id;
  row.classList.toggle("is-done", task.done);

  const title = qs(".task-title", row);
  title.id = titleId;
  title.textContent = task.title;

  // The checkbox is named by the title, and each button is described by it,
  // so a screen reader says "Delete, button, Buy milk" instead of just "Delete".
  const toggle = qs(".task-toggle", row);
  toggle.checked = task.done;
  toggle.setAttribute("aria-labelledby", titleId);
  for (const button of qsa("button", row)) {
    button.setAttribute("aria-describedby", titleId);
  }
}

/**
 * Makes list show the tasks that pass filter, in order.
 *
 * Rows are matched to tasks by data-id and updated in place, and only rows
 * that appear or disappear are added or removed. Rebuilding every row on each
 * change would look the same, but it would drop keyboard focus and swallow a
 * click whenever the list changed under the pointer.
 */
export function renderTasks(list, tasks, filter) {
  const visible = filterTasks(tasks, filter);
  const ids = new Set(visible.map((task) => task.id));
  for (const row of [...list.children]) {
    if (!ids.has(row.dataset.id)) row.remove();
  }

  const rows = new Map([...list.children].map((row) => [row.dataset.id, row]));
  visible.forEach((task, index) => {
    const row = rows.get(task.id) ?? createRow(list.ownerDocument);
    fillRow(row, task);
    const current = list.children[index] ?? null;
    if (row !== current) list.insertBefore(row, current);
  });
}

/**
 * Focuses the control named by control (a data-action) in the row of task id.
 * When that task is no longer shown, it focuses the checkbox of the row that
 * took its place instead, or of the last row.
 * @returns {boolean} false when the list is empty and nothing was focused
 */
export function focusTask(list, { id, index, control }) {
  const rows = [...list.children];
  const same = rows.find((row) => row.dataset.id === id);
  const row = same ?? rows[Math.min(index, rows.length - 1)];
  if (row === undefined) return false;
  qs(`[data-action="${same ? control : "toggle"}"]`, row).focus();
  return true;
}

/**
 * Event delegation: one listener on root handles an event from any element
 * inside it that matches selector, including elements added later. The
 * handler gets the event and the matching element.
 * @returns {() => void} a function that removes the listener
 */
export function delegate(root, type, selector, handler) {
  function listener(event) {
    const match = event.target instanceof Element ? event.target.closest(selector) : null;
    if (match !== null && root.contains(match)) handler(event, match);
  }
  root.addEventListener(type, listener);
  return () => root.removeEventListener(type, listener);
}

/** Renders the first time and starts listening. Call it once. */
start(filter = "all") {
  this.#filter = filter;
  this.#store.subscribe(() => this.render());

  this.#form.addEventListener("submit", (event) => this.#onSubmit(event));

  // The rows come and go, so one listener on the list handles them all.
  delegate(this.#list, "click", "[data-action]", (event, control) => this.#onAction(control));
  delegate(this.#list, "dblclick", ".task-title", (event, title) => this.#edit(rowOf(title).row));
  delegate(this.#list, "keydown", ".task-title-input", (event, input) =>
    this.#onEditKey(event, input),
  );
  // blur does not bubble, so delegation listens for focusout, which does.
  delegate(this.#list, "focusout", ".task-title-input", (event, input) =>
    this.#save(input, { refocus: false }),
  );

  delegate(this.#footer, "click", "a[data-filter]", (event, link) =>
    this.#onFilterLink(event, link),
  );
  qs("#clear-completed", this.#footer).addEventListener("click", () => this.#onClearCompleted());
  window.addEventListener("popstate", () => this.#show(filterFromSearch(location.search)));

  this.render();
}

#onEditKey(event, input) {
  // While an input method (for Japanese or Chinese, say) is composing, Enter
  // confirms the composition. It must not save the task as well.
  if (event.isComposing) return;
  if (event.key === "Enter") {
    // Saving moves focus to the row's Edit button. Without preventDefault,
    // this same Enter would go on to press that button and reopen the editor.
    event.preventDefault();
    this.#save(input, { refocus: true });
  } else if (event.key === "Escape") {
    this.#cancel(input);
  }
}
